const report = $input.first().json;
const items = Array.isArray(report.items) ? report.items : [];
const count = function (key) {
  const acc = {};
  for (const item of items) { const k = item[key] || 'Sin dato'; acc[k] = (acc[k] || 0) + 1; }
  return acc;
};
const byLocation = {};
for (const item of items) {
  const loc = item.locationName || 'Sin sede';
  if (!byLocation[loc]) byLocation[loc] = { total: 0 };
  byLocation[loc].total += 1;
  byLocation[loc][item.status] = (byLocation[loc][item.status] || 0) + 1;
}
const byStatus = count('status');
const bySpecialty = count('specialtyName');
const tracked = ['APPROVED', 'COMPLETED', 'NO_SHOW', 'CANCELLED'];
const lines = [];
lines.push('Resumen operativo del ' + report.date + ' (' + report.timezone + ')');
lines.push('Total de citas: ' + items.length);
lines.push('');
lines.push('Por estado:');
for (const s of tracked) lines.push('- ' + s + ': ' + (byStatus[s] || 0));
for (const s of Object.keys(byStatus)) if (!tracked.includes(s)) lines.push('- ' + s + ': ' + byStatus[s]);
lines.push('');
lines.push('Por sede:');
for (const loc of Object.keys(byLocation).sort()) {
  const d = byLocation[loc];
  lines.push('- ' + loc + ': ' + d.total + ' (' + tracked.map(function (s) { return s + ' ' + (d[s] || 0); }).join(', ') + ')');
}
lines.push('');
lines.push('Por especialidad:');
for (const sp of Object.keys(bySpecialty).sort()) lines.push('- ' + sp + ': ' + bySpecialty[sp]);
lines.push('');
lines.push('Incidencias de API: ninguna.');
lines.push('Datos sintéticos de laboratorio.');
return [{ json: { date: report.date, total: items.length, byStatus: byStatus, byLocation: byLocation, bySpecialty: bySpecialty, subject: 'Resumen operativo ' + report.date + ': ' + items.length + ' citas', body: lines.join('\n') } }];
